import{_ as r,o,c as a,ag as t}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"WorkerDeployment — takoform_worker_deployment","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/worker-deployment.md","filePath":"proposals/edge/worker-deployment.md"}'),s={name:"proposals/edge/worker-deployment.md"};function i(n,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="workerdeployment-—-takoform-worker-deployment" tabindex="-1">WorkerDeployment — <code>takoform_worker_deployment</code> <a class="header-anchor" href="#workerdeployment-—-takoform-worker-deployment" aria-label="Permalink to &quot;WorkerDeployment — `takoform_worker_deployment`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>An operator moves traffic between Worker Versions of one Module Worker: canary a new version at a small share, promote it, or roll back — all by re-weighting, never by mutating a revision.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>deployment</code>. This is the only mutable path for traffic movement.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p><code>versions</code> lists one to eight entries of <code>workerVersion</code> plus <code>weight</code> in basis points. Weights must sum to exactly 10000 across entries; the sum is host-validated semantics because a JSON schema cannot add weights. Each request is served entirely by one selected version; a client never observes a blend of two versions within one request.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Version selection is a single atomic fact per worker. Splitting weights across resources would allow interleavings in which the observable sum is temporarily wrong.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>Per-request routing rules, header- or cookie-pinned sessions, and geographic steering carry different selection semantics and belong to separate Forms.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None; the deployment selects revisions, it does not use capabilities.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>A deployment referencing a deleted version must fail closed. Rollback is re-weighting to a previous version and must not require recreating it. Deleting the deployment stops traffic selection but never deletes the worker or its versions.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The gradual-rollout deployment model of a proven edge platform, reduced to its portable core: exact basis-point weights over immutable versions.</p>',19)])])}const u=r(s,[["render",i]]);export{m as __pageData,u as default};
